calls = []
def f(a,b):
    calls.append((a,b))
    if (a==0):
        return b
    if (a%2==1):
        return 2*f((a-1)/2,b)
    return b+f(a-1,b)
print(f(15,10))
print('call chain:', calls)
calls.clear()
# closed form check: f(a,b) == (a+1)*b for small non-negative integers a
print('f(a,b)==(a+1)*b for a<200:', all(f(a,7)==(a+1)*7 for a in range(200)))
